var i=`0036-roso`;var t=`world-0036`;var a=`PL`;var o=`eastern-europe`;var s=4;var r=80;var l={en:`Rosół`,ua:`Росул`};var g={en:`A classic dish from Poland, featuring whole chicken, yellow onion, carrot, parsley root. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: ціла курка, жовта цибуля, морква, корінь петрушки. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 70 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 70 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:70,i:[[`whole-chicken`,900,`g`],[`water`,2e3,`ml`],[`yellow-onion`,130,`g`],[`carrot`,160,`g`],[`parsley-root`,90,`g`],[`celeriac`,70,`g`],[`bay-leaf`,1,`leaf`]]},{en:`Cook the listed ingredients in simmering water for about 7 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 7 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:7,i:[[`egg-noodles`,180,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`parsley`,16,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:i,id:t,country:`PL`,region:o,servings:4,minutes:80,title:l,text:g,steps:m};export{a as country,d as default,t as id,r as minutes,o as region,s as servings,i as slug,m as steps,g as text,l as title};